/**
 * Desktop UI extension points for Plugin API v2.
 *
 * `declarative` points are drawn by Tape from manifest data (a title, an icon
 * token, a command to run or a workspace to open). `iframe` points render the
 * plugin's own HTML from `entrypoints.ui` inside a sandboxed frame that
 * follows the active theme. Plugins never touch the host DOM.
 */
export const EXTENSION_POINT_CATALOG = [
    { id: 'sidebar.item', form: 'declarative', status: 'available', maxItemsPerPlugin: 2, description: 'Entry in the sidebar that opens one of the plugin workspaces.' },
    { id: 'workspace', form: 'iframe', status: 'available', maxItemsPerPlugin: 3, description: 'Full view inside the main area, rendered from entrypoints.ui.' },
    { id: 'contextMenu.track', form: 'declarative', status: 'available', maxItemsPerPlugin: 3, entity: 'track', description: 'Right-click menu item on a track.' },
    { id: 'contextMenu.album', form: 'declarative', status: 'available', maxItemsPerPlugin: 3, entity: 'album', description: 'Right-click menu item on an album.' },
    { id: 'contextMenu.artist', form: 'declarative', status: 'available', maxItemsPerPlugin: 3, entity: 'artist', description: 'Right-click menu item on an artist.' },
    { id: 'contextMenu.label', form: 'declarative', status: 'available', maxItemsPerPlugin: 3, entity: 'label', description: 'Right-click menu item on a label.' },
    { id: 'contextMenu.playlist', form: 'declarative', status: 'available', maxItemsPerPlugin: 3, entity: 'playlist', description: 'Right-click menu item on a playlist.' },
    { id: 'contextMenu.folder', form: 'declarative', status: 'available', maxItemsPerPlugin: 3, entity: 'folder', description: 'Right-click menu item on a library folder.' },
    { id: 'contextMenu.selection', form: 'declarative', status: 'available', maxItemsPerPlugin: 3, entity: 'selection', description: 'Right-click menu item on a multi-track selection.' },
    { id: 'detail.section.track', form: 'iframe', status: 'available', maxItemsPerPlugin: 1, entity: 'track', description: 'Section in the track details view.' },
    { id: 'detail.section.album', form: 'iframe', status: 'available', maxItemsPerPlugin: 1, entity: 'album', description: 'Section in the album view.' },
    { id: 'detail.section.artist', form: 'iframe', status: 'available', maxItemsPerPlugin: 1, entity: 'artist', description: 'Section in the artist view.' },
    { id: 'detail.section.playlist', form: 'iframe', status: 'available', maxItemsPerPlugin: 1, entity: 'playlist', description: 'Section in the playlist view.' },
    { id: 'row.badge.track', form: 'declarative', status: 'available', maxItemsPerPlugin: 1, entity: 'track', description: 'Short text badge in track rows, computed by a worker command.' },
    { id: 'settings.section', form: 'declarative', status: 'available', maxItemsPerPlugin: 1, description: 'Settings form generated by Tape from manifest.settings.' },
    { id: 'command', form: 'declarative', status: 'available', maxItemsPerPlugin: 10, description: 'Command in the command palette.' },
    { id: 'player.panel', form: 'iframe', status: 'available', maxItemsPerPlugin: 1, description: 'Panel next to the player, such as lyrics or notes.' },
    { id: 'library.filters', form: 'declarative', status: 'reserved', maxItemsPerPlugin: 2, description: 'Library filter applied by Tape over track fields.' },
    { id: 'player.controls', form: 'declarative', status: 'reserved', maxItemsPerPlugin: 1, description: 'Compact control in the player bar.' },
    { id: 'toolbar.library', form: 'declarative', status: 'reserved', maxItemsPerPlugin: 2, description: 'Action in the library header.' },
    { id: 'statusbar.item', form: 'declarative', status: 'reserved', maxItemsPerPlugin: 1, description: 'Item in the status bar.' },
    { id: 'skin', form: 'iframe', status: 'reserved', maxItemsPerPlugin: 1, description: 'Full replacement of the Desktop interface over the client core.' },
];
const BY_ID = new Map(EXTENSION_POINT_CATALOG.map((entry) => [entry.id, entry]));
export function getExtensionPoint(id) {
    return BY_ID.get(id);
}
/** Icon tokens Tape can draw for declarative contributions. */
export const PLUGIN_ICON_TOKENS = [
    'plugin', 'wishlist', 'music', 'album', 'artist', 'playlist', 'folder', 'tag', 'search', 'sparkle',
    'link', 'upload', 'download', 'share', 'chart', 'clock', 'star', 'heart', 'info', 'settings',
];
